// ❌ MAGIC NUMBERS — ¿qué significan 100, 5f y 0.3f?
public class Player : MonoBehaviour
{
    private int health = 100;
    private float speed = 5f;
    private float jumpCooldown = 0.3f;

    void TakeDamage() { health -= 25; }
    void Update()     { rb.velocity = transform.forward * 5f; }
}

// ✅ SIN MAGIC NUMBERS — nombres descriptivos
public class Player : MonoBehaviour
{
    private const int MaxHealth      = 100;
    private const float MoveSpeed    = 5f;
    private const float JumpCooldown = 0.3f;
    private const int BaseDamage     = 25;

    void TakeDamage()  { health -= BaseDamage; }
    void Update()      { rb.velocity = transform.forward * MoveSpeed; }
}

