public class PlayerShoot : MonoBehaviour
{
    private const int MaxAmmo = 30;
    private const float FireRate = 0.5f;
    private int ammo;

    void Start() { ammo = MaxAmmo; }

    public void Shoot()
    {
        ammo--;
        Invoke("Shoot", FireRate);
    }
}

alternateAnswers:
public class PlayerShoot : MonoBehaviour
{
    private const int StartingAmmo = 30;
    private const float ShootCooldown = 0.5f;
    private int ammo = StartingAmmo;
    public void Shoot() { ammo--; Invoke("Shoot", ShootCooldown); }
}
